```javascript
window.addEventListener('storage', (event) => {
  if (event.storageArea !== localStorage || event.key !== 'theme') return;
  const theme = event.newValue === 'dark' ? 'dark' : 'light';
  document.documentElement.dataset.theme = theme;
});
```
